function validate(input) {
  const [{ UserVisits = [] }] = input;
  for (const [user, date] of UserVisits) {
    if (user === null || date === null) return 'UserVisits rows may not contain null.';
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `visit_date ${date} is not a YYYY-MM-DD date.`;
    if (date > '2021-01-01') return `visit_date ${date} is after today (2021-01-01).`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = (n) => Math.floor(rand() * n);
  const start = Date.UTC(2020, 0, 1);
  const toDate = (offset) => new Date(start + offset * 86400000).toISOString().slice(0, 10);
  const users = small ? 4 : 300;
  const rows = small ? pick(9) : 2000;
  const UserVisits = [];
  for (let k = 0; k < rows; k++) {
    // Small cases sometimes repeat the previous visit, since a user may visit twice in a day.
    if (small && UserVisits.length > 0 && rand() < 0.15) { UserVisits.push(UserVisits[UserVisits.length - 1].slice()); continue; }
    // Offsets run up to 366, which is 2021-01-01 itself (2020 is a leap year).
    const offset = small ? 300 + pick(67) : pick(367);
    UserVisits.push([1 + pick(users), toDate(offset)]);
  }
  return [{ UserVisits }];
}
